($q${"type":"true_false","form":"bai_tap","topic":"Cấu trúc chất rắn, lỏng, khí theo mô hình động học phân tử","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Khi nói về mô hình động học phân tử, câu nào đúng, câu nào sai?</p>","explanation":"","statements":[{"text":"Giữa các phân tử có lực tương tác. Độ lớn của những lực này phụ thuộc vào cấu tạo của vật chất.","answer":true},{"text":"Các phân tử chuyển động không ngừng, chuyển động này càng nhanh thì nhiệt độ của vật càng cao","answer":true},{"text":"Các chất được cấu tạo từ những hạt có kích thước rất nhỏ gọi là phân tử. Giữa các phân tử có khoảng cách.","answer":true},{"text":"Khi khoảng cách giữa các phân tử lớn thì lực đẩy mạnh hơn lực hút","answer":false}]}$q$::jsonb, 195, $q$Cấu trúc chất rắn, lỏng, khí theo mô hình động học phân tử$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Cấu trúc chất rắn, lỏng, khí theo mô hình động học phân tử","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Theo mô hình động học phân tử về cấu tạo chất thì</p>","explanation":"","statements":[{"text":"Các chất được cấu tạo từ các hạt riêng biệt là phân tử","answer":true},{"text":"Các phân tử chuyển động hỗn loạn không ngừng. Nhiệt độ của vật càng cao thì tốc độ chuyển động của các phân tử cấu tạo nên vật càng lớn.","answer":true},{"text":"Giữa các phân tử có lực hút và đẩy gọi chung là lực liên kết phân tử.","answer":true},{"text":"Giải thích được cấu trúc của các chất rắn, chất lỏng, chất khí và nhưng không giải thích được sự chuyển thể.","answer":false}]}$q$::jsonb, 195, $q$Cấu trúc chất rắn, lỏng, khí theo mô hình động học phân tử$q$),
