($q${"type":"true_false","form":"bai_tap","topic":"Cấu trúc chất rắn, lỏng, khí theo mô hình động học phân tử","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Trong các nhận định sau đây về cấu trúc chất rắn, hãy cho biết câu nào đúng, câu nào sai?</p>","explanation":"","statements":[{"text":"Các phân tử chất rắn ở rất gần nhau và sắp xếp một cách chặt chẽ, có trật tự","answer":true},{"text":"Chất rắn có thể tích và hình dạng không xác định","answer":false},{"text":"Muối ăn và kim cương là chất rắn vô định hình","answer":false},{"text":"Chất rắn kết tinh có cấu trúc tinh thể","answer":true}]}$q$::jsonb, 195, $q$Cấu trúc chất rắn, lỏng, khí theo mô hình động học phân tử$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Cấu trúc chất rắn, lỏng, khí theo mô hình động học phân tử","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Khi nói về chất rắn:</p>","explanation":"","statements":[{"text":"Chất rắn vô định hình là chất mà các hạt (phân tử, nguyên tử, ion) cấu tạo nên nó ở thể rắn liên kết với nhau một cách chặt chẽ sắp xếp theo một trật tự hình học xác định tạo thành các mạng tinh thể.","answer":false},{"text":"Chất rắn kết tinh là chất ở thể rắn mà các hạt tạo nên nó không tạo thành mạng tinh thể.","answer":false},{"text":"Ở điều kiện thường, đa số các kim loại là các chất kết tinh.","answer":true},{"text":"Thủy tinh, nhựa đường, các chất dẻo là các chất vô định hình.","answer":true}]}$q$::jsonb, 195, $q$Cấu trúc chất rắn, lỏng, khí theo mô hình động học phân tử$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Cấu trúc chất rắn, lỏng, khí theo mô hình động học phân tử","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Nội dung sau đây đề cập đến chất ở thể lỏng.</p>","explanation":"","statements":[{"text":"Khoảng cách trung bình giữa các phân tử trong chất lỏng lớn hơn trong chất rắn và nhỏ hơn trong chất khí.","answer":true},{"text":"Lực liên kết giữa các phân tử ở thể lỏng lớn hơn ở thể khí và nhỏ hơn ở thể rắn.","answer":true},{"text":"Lực liên kết phân tử giữ được các phân tử không bị phân tán xa nhau do đó chất lỏng có thể tích riêng xác định.","answer":true},{"text":"Các phân tử ở thể lỏng, dao động xung quanh vị trí cân bằng di chuyển được nên khối chất lỏng rất khó bị nén và có hình dạng xác định.","answer":false}]}$q$::jsonb, 195, $q$Cấu trúc chất rắn, lỏng, khí theo mô hình động học phân tử$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Cấu trúc chất rắn, lỏng, khí theo mô hình động học phân tử","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Các câu sau đây, câu nào đúng, câu nào sai?</p>","explanation":"","statements":[{"text":"Giữa các nguyên tử, phân tử không có khoảng cách","answer":false},{"text":"Lực tương tác giữa các phân tử của vật ở thể rắn lớn hơn lực tương tác giữa các phân tử của vật ở thể lỏng, thể khí.","answer":true},{"text":"Các nguyên tử, phân tử chất rắn dao động xung quanh các vị trí cân bằng không cố định.","answer":false},{"text":"Các nguyên tử, phân tử chất lỏng dao động xung quanh các vị trí cân bằng không cố định.","answer":true}]}$q$::jsonb, 195, $q$Cấu trúc chất rắn, lỏng, khí theo mô hình động học phân tử$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Cấu trúc chất rắn, lỏng, khí theo mô hình động học phân tử","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Trong các nhận định sau đây, nhận định nào <strong>đúng</strong>, nhận định nào <strong>sai</strong>?</p>","explanation":"","statements":[{"text":"Ở thể rắn, các phân tử dao động quanh vị trí cân bằng luôn thay đổi.","answer":false},{"text":"Các phân tử chuyển động càng nhanh thì nhiệt độ của vật càng cao","answer":true},{"text":"Chất rắn kết tinh không có hình dạng và cấu trúc tinh thể xác định.","answer":false},{"text":"Ở thể khí, các phân tử ở rất gần nhau và chuyển động hỗn loạn không ngừng.","answer":false}]}$q$::jsonb, 195, $q$Cấu trúc chất rắn, lỏng, khí theo mô hình động học phân tử$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Cấu trúc chất rắn, lỏng, khí theo mô hình động học phân tử","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Nội dung sau đây đề cập đến chất ở thể khí.</p>","explanation":"","statements":[{"text":"Ở thể khí, khoảng cách giữa các phân tử lớn gấp hàng chục lần kích thước của chúng.","answer":true},{"text":"Lực tương tác giữa các phân tử rất yếu (trừ khi va chạm nhau) nên các phân tử chuyển động hoàn toàn hỗn loạn.","answer":true},{"text":"Khối khí không có hình dạng và thể tích riêng mà nó có hình dạng và thể tích của bình chứa nó.","answer":true},{"text":"Rất khó nén chất ở thể khí.","answer":false}]}$q$::jsonb, 195, $q$Cấu trúc chất rắn, lỏng, khí theo mô hình động học phân tử$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Cấu trúc chất rắn, lỏng, khí theo mô hình động học phân tử","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Nội dung sau đây đề cập đến chất ở thể khí.</p>","explanation":"","statements":[{"text":"Các phân tử ở xa nhau hơn so với các phân tử trong chất lỏng.","answer":true},{"text":"Khoảng cách giữa các phân tử rất lớn so với kích thước của chúng nên lực tương tác giữa các phân tử hầu như không đáng kể ngay cả khi va chạm nhau.","answer":false},{"text":"Các phân tử khí chuyển động hỗn loạn về mọi phía chiếm toàn bộ không gian của bình chứa.","answer":true},{"text":"Một lượng khí nhất định không có thể tích và hình dạng riêng mà có thể tích và hình dạng của bình chứa.","answer":true}]}$q$::jsonb, 195, $q$Cấu trúc chất rắn, lỏng, khí theo mô hình động học phân tử$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Cấu trúc chất rắn, lỏng, khí theo mô hình động học phân tử","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Các nội dung sau đề cập đến các thể của chất.</p>","explanation":"","statements":[{"text":"Ở nhiệt độ hàng triệu độ chất không tồn tại ở các thể rắn, lỏng, khí mà ở một thể đặc biệt gọi là plasma.","answer":true},{"text":"Ở thể plasma chất không tồn tại dưới dạng các nguyên tử phân tử mà dưới dạng các ion.","answer":true},{"text":"Thể plasma rất ít gặp trong vũ trụ.","answer":false},{"text":"Trên Trái Đất có trên 99% các chất tồn tại ở thể plasma.","answer":false}]}$q$::jsonb, 195, $q$Cấu trúc chất rắn, lỏng, khí theo mô hình động học phân tử$q$),
