($q${"type":"true_false","form":"bai_tap","topic":"Vận dụng ΔU = A + Q","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Xét hệ thức Định luật I của nhiệt động lực học: ΔU = A + Q.</p>","explanation":"","statements":[{"text":"Q \\> 0, hệ nhận nhiệt lượng từ hệ khác.","answer":true},{"text":"Q \\< 0, hệ truyền nhiệt lượng cho hệ khác.","answer":true},{"text":"A \\> 0, hệ nhận công từ hệ khác.","answer":true},{"text":"A \\< 0, hệ thực hiện công lên hệ khác.","answer":true}]}$q$::jsonb, 200, $q$Vận dụng ΔU = A + Q$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Vận dụng ΔU = A + Q","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Các biểu thức sau đây mô tả các quá trình thay đổi nội năng nào?</p>","explanation":"","statements":[{"text":"ΔU = Q, khi Q \\> 0 và khi Q \\< 0: Hệ chỉ trao đổi nhiệt với bên ngoài.","answer":true},{"text":"ΔU = A, khi A \\> 0 và khi A \\< 0: Hệ chỉ trao đổi công với bên ngoài.","answer":true},{"text":"ΔU = A + Q, khi Q \\> 0 và khi A \\< 0: Hệ nhận nhiệt để thực hiện công.","answer":true},{"text":"ΔU = A + Q, khi Q \\< 0 và khi A \\> 0: Hệ nhận công để nhả nhiệt.","answer":true}]}$q$::jsonb, 200, $q$Vận dụng ΔU = A + Q$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Tính nhiệt lượng theo nhiệt dung riêng","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Nhiệt dung riêng là</p>","explanation":"","statements":[{"text":"Lượng nhiệt cần cung cấp để tăng nhiệt độ của 1 kg chất lên 1 độ K.","answer":true},{"text":"Lượng nhiệt cần cung cấp để tăng nhiệt độ của 1 kg chất lên 1 độ C.","answer":true},{"text":"Lượng nhiệt cần cung cấp để giảm nhiệt độ của 1 kg chất xuống 1 độ K.","answer":false},{"text":"Lượng nhiệt cần cung cấp đề giảm nhiệt độ của 1 kg chất xuống 1 độ C.","answer":false}]}$q$::jsonb, 201, $q$Tính nhiệt lượng theo nhiệt dung riêng$q$)) as v(q, tid, tname)
where not exists (select 1 from public.question_bank b where b.content_hash = public.question_content_hash(v.q));
