from (values ($q${"type":"true_false","form":"bai_tap","topic":"Tính nhiệt lượng theo nhiệt dung riêng","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Với cùng một lượng nhiệt cung cấp, chất có nhiệt dung riêng</p>","explanation":"","statements":[{"text":"Lớn hơn sẽ tăng nhiệt độ nhanh hơn.","answer":false},{"text":"Nhỏ hơn sẽ tăng nhiệt độ chậm hơn.","answer":false},{"text":"Lớn hơn sẽ tăng nhiệt độ chậm hơn.","answer":true},{"text":"Nhỏ hơn sẽ tăng nhiệt độ nhanh hơn.","answer":true}]}$q$::jsonb, 201, $q$Tính nhiệt lượng theo nhiệt dung riêng$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Tính nhiệt lượng theo nhiệt dung riêng","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Nhiệt dung riêng có ảnh hưởng đến</p>","explanation":"","statements":[{"text":"lượng nhiệt cần thiết để tăng nhiệt độ của một chất.","answer":true},{"text":"tốc độ tăng nhiệt độ của một chất.","answer":true},{"text":"màu sắc của một chất.","answer":false},{"text":"mùi của một chất.","answer":false}]}$q$::jsonb, 201, $q$Tính nhiệt lượng theo nhiệt dung riêng$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Cho các phát biểu sau, phát biểu nào đúng? Phát biểu nào sai?</p>","explanation":"","statements":[{"text":"Nhiệt lượng cần cung cấp cho một lượng chất lỏng hoá hơi ở nhiệt độ không đổi không phụ thuộc vào khối lượng và bản chất của chất lỏng.","answer":false},{"text":"Nhiệt hoá hơi riêng của một chất lỏng là nhiệt lượng cần để làm cho 1 kg chất lỏng đó hoá hơi hoàn toàn ở nhiệt độ xác định.","answer":true},{"text":"Nhiệt hoá hơi riêng của một chất tăng khi nhiệt độ tăng.","answer":false},{"text":"Ứng dụng của nhiệt hoá hơi như: trong các thiết bị làm lạnh (như máy điều hoà nhiệt độ, dàn lạnh, dàn bay hơi,…), nồi hấp tiệt trùng trong y học, thiết bị xử lí rác thải ứng dựng công nghệ hoá hơi,…","answer":true}]}$q$::jsonb, 202, $q$Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Nóng chảy, đông đặc, hoá hơi, ngưng tụ","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Nước có vai trò rất quan trọng trong cuộc sống. Sự biến đổi các trạng thái của nước tạo nên một vòng tuần hoàn được gọi là vòng tuần hoàn của nước. Hình bên mô tả một cách đơn giản vòng tuần hoàn của nước.</p>","explanation":"","statements":[{"text":"Trong vòng tuần hoàn của nước như hình bên, quá trình A\n\nlà sự bay hơi của các phân tử nước ở bề mặt sông, hồ,…","answer":true},{"text":"Trong quá trình B, nước đã chuyển từ thể khí sang thể lỏng.","answer":true},{"text":"Trong sự chuyển thể ở quá trình B, hơi nước đã phải hấp thu một lượng nhiệt lớn từ không khí.","answer":false},{"text":"Năng lượng cung cấp cho nước thực hiện quá trình hóa hơi chủ yếu được cung cấp từ Mặt Trời.","answer":true}]}$q$::jsonb, 196, $q$Nóng chảy, đông đặc, hoá hơi, ngưng tụ$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Nóng chảy, đông đặc, hoá hơi, ngưng tụ","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Đồ thị hình vẽ sau biểu diễn sự phụ thuộc nhiệt độ sôi của nước vào độ cao so với mặt biển, căn cứ vào số liệu trên hình vẽ, hãy chọn câu trả lời đúng</p>","explanation":"","statements":[{"text":"Càng lên cao, nhiệt độ sôi của nước càng tăng","answer":false},{"text":"Ở độ cao 3000 m thì nhiệt độ sôi của nước là 90$^{o}$C","answer":true},{"text":"Ở độ cao mặt nước biển, nhiệt độ sôi của nước là 80$^{o}$C","answer":false},{"text":"Ở độ cao 6000 m, nhiệt độ sôi của nước là 100$^{o}$C","answer":false}]}$q$::jsonb, 196, $q$Nóng chảy, đông đặc, hoá hơi, ngưng tụ$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Thang Celsius và thang Kelvin","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một nhiệt kế có phạm vi đo từ 263K đến 1273K dùng để đo nhiệt độ của các lò nung.</p>","explanation":"","statements":[{"text":"Phạm vi đo trong thang Celsius là -10$^{o}$C đến 1000$^{o}$C","answer":true},{"text":"Phạm vi đo trong thang Fehrenheit là 14$^{o}$F đến 1832$^{o}$F","answer":true},{"text":"Nhiệt kế có thể đo nhiệt độ của lò nung tại 1083$^{o}$C","answer":true},{"text":"Nhiệt kế có thể đo nhiệt độ của lò nugn tại 1745$^{o}$F","answer":true}]}$q$::jsonb, 197, $q$Thang Celsius và thang Kelvin$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Nội năng và hai cách làm biến đổi nội năng","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Các vật thể được cấu tạo từ các phân tử. Người ta gọi tổng động năng và thế năng tương tác của các phân tử cấu tạo nên vật là nội năng của vật.</p>","explanation":"","statements":[{"text":"Nội năng là một dạng năng lượng.","answer":true},{"text":"Nội năng của một vật phụ thuộc vào thể tích và nhiệt độ của vật","answer":true},{"text":"Hai vật A và B có cùng chất liệu. Nếu nội năng của vật A lớn hơn vật B thì nhiệt độ của vật A\n\ncũng lớn hơn vật B.","answer":false},{"text":"Có hai cách làm thay đổi nội năng của một vật là thực hiện công và truyền nhiệt.","answer":true}]}$q$::jsonb, 199, $q$Nội năng và hai cách làm biến đổi nội năng$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Nội năng và hai cách làm biến đổi nội năng","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Khi thực hiện quá trình truyền nhiệt cho vật, ta nói rằng vật nhận thêm nhiệt lượng nên nội năng thay đổi, giữa nội năng và nhiệt lượng có một mối liên hệ qua lại với nhau.</p>","explanation":"","statements":[{"text":"Nhiệt lượng là số đo độ biến thiên nội năng của vật trong quá trình truyền nhiệt.","answer":true},{"text":"Đơn vị của nhiệt lượng cũng là đơn vị của nội năng.","answer":true},{"text":"Một vật lúc nào cũng có nội năng, do đó lúc nào vật cũng có nhiệt lượng.","answer":false},{"text":"Một vật có nội năng lớn khi cho tiếp xúc với vật khác có nội năng nhỏ hơn thì sẽ xảy ra quá trình truyền nhiệt.","answer":false}]}$q$::jsonb, 199, $q$Nội năng và hai cách làm biến đổi nội năng$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Vận dụng ΔU = A + Q","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một lượng khí chứa trong một xilanh có pittong di chuyển được. Ở trạng thái cân bằng, chất khí chiếm thể tích V và tác dụng lên pittong một áp suất 4. 10$^{5}$ N/m$^{2}$. Khối khí nhận một nhiệt lượng 1000 J giãn nở đẩy pittong lên làm thể tích khí tăng thêm 0,003 m$^{3}$. Coi rằng áp suất chất khí không đổi. Khẳng định nào sau đây là đúng, sai?</p>","explanation":"","statements":[{"text":"Lượng khí bên trong xilanh nhận nhiệt và sinh công làm biến đổi nội năng.","answer":true},{"text":"Theo quy ước, khối khí nhận nhiệt và sinh công nên\n\nA \\> 0; Q \\> 0","answer":false},{"text":"Công mà khối khí thực hiện có độ lớn bằng 1200 J","answer":true},{"text":"Độ biến thiên nội năng của khối khí ΔU = −200 J","answer":true}]}$q$::jsonb, 200, $q$Vận dụng ΔU = A + Q$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Tính nhiệt lượng theo nhiệt dung riêng","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Người ta dùng ấm điện có công suất tỏa nhiệt P = 800W để đun một lượng nước có khối lượng m. Hình bên là đồ thị biểu diễn sự phụ thuộc nhiệt lượng Q cung cấp cho nước theo nhiệt độ t của nước. Tại thời điểm ban đầu (τ = 0), nhiệt độ của nước là 25$^{∘}$C. Lấy nhiệt dung riêng của nước là c = 4200 J/kg. K. Coi hiệu suất của ấm điện là 100%. Xét tính đúng sai của các phát biểu sau:</p>","explanation":"","statements":[{"text":"Giá trị của m là 1,2 kg.","answer":true},{"text":"Nhiệt lượng cần cung cấp cho nước từ thời điểm τ = 0 đến khi nước bắt đầu sôi là 387 kJ.","answer":false},{"text":"Khi nước bắt đầu sôi, nếu tiếp tục đun thì nước sẽ hóa hơi và nhiệt độ của nước luôn tăng trong quá trình hóa hơi.","answer":false},{"text":"Thời gian đun sôi nước kế từ thời điểm τ = 0 là 472,5 giây.","answer":true}]}$q$::jsonb, 201, $q$Tính nhiệt lượng theo nhiệt dung riêng$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Tính nhiệt lượng cần cung cấp cho 5 kg nước đá ở −10$^{∘}$C chuyển hoàn toàn thành nước ở 0$^{∘}$C. Cho biết nhiệt dung riêng của nước đá là 2090 J/kg.K và nhiệt nóng chảy riêng của nước đá 3,4. 10$^{5}$ J/kg.</p>","explanation":"","statements":[{"text":"Nhiệt lượng cần cung cấp cho 5 kg nước đá ở −10$^{∘}$C chuyển thành nước đá ở 0$^{∘}$C là\n\n1045000 J.","answer":false},{"text":"Nhiệt lượng cần cung cấp để 5 kg nước đá ở 0$^{∘}$C chuyển thành nước là 17.10$^{5}$ J.","answer":true},{"text":"Nhiệt lượng cần cung cấp cho 5 kg nước đá ở −10$^{∘}$C chuyển thành nước ở 0$^{∘}$C là\n\n18045000 J.","answer":false},{"text":"Nếu tiếp tục cung cấp nhiệt lượng thì nước sẽ chuyển hoá thành hơi (thể khí).","answer":true}]}$q$::jsonb, 202, $q$Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một khối nước đá khối lượng m = 2kg ở nhiệt độ −5$^{0}$C. Cho biết nhiệt dung riêng của nước đá và nước lần lượt là 2000 J/kg. K, 4200J/kg. K; nhiệt nóng chảy riêng của nước đá ở 0$^{0}$C là λ = 3,4.10$^{5}$J/kg; nhiệt hoá hơi của nước ở 100$^{0}$C là L = 2,3.10$^{6}$J/kg. Trong các câu sau đây, câu nào đúng, sai?</p>","explanation":"","statements":[{"text":"Nhiệt lượng nước đá thu vào để tăng nhiệt độ từ −5$^{0}$C đến 0$^{0}$C là 18 kJ","answer":false},{"text":"Nhiệt lượng nước đá ở 0$^{0}$C thu vào để nóng chảy hoàn toàn là 840 kJ","answer":false},{"text":"Nhiệt lượng nước ở 100$^{0}$C thu vào để hoá hơi hoàn toàn là 4600 kJ","answer":true},{"text":"Nhiệt lượng tổng cộng cần cung cấp để nước đá ở −5$^{0}$C biến thành hơi hoàn toàn ở 100$^{0}$C là 6140 kJ","answer":true}]}$q$::jsonb, 202, $q$Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Nhiệt độ và cân bằng nhiệt","difficulty":"kho","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một bát bằng đồng nặng 150 g đựng 220 g nước đều ở nhiệt độ 20$^{0}$C. Một miếng đồng hình trụ khối lượng 300 g ở nhiệt độ cao rơi vào bát nước làm nước sôi và chuyển 5,00 g nước thành hơi. Nhiệt độ cuối của hệ là 100$^{0}$C. Biết nhiệt dung riêng của đồng là cđồng = 380J/kg. K; nhiệt dung riêng của nước $c_{H}$2O = 4200J/kg. K và nhiệt hoá hơi riêng của nước L = 2,26.10$^{6}$J/kg. K. Trong các câu sau đây, câu nào đúng, sai?</p>","explanation":"","statements":[{"text":"Bát đồng và nước nhận nhiệt lượng từ miếng đồng.","answer":true},{"text":"Nhiệt lượng mà nước nhận được để tăng nhiệt độ từ 20$^{0}$C đến 100$^{0}$C là 124320J","answer":false},{"text":"Nhiệt lượng bát đồng nhận được để tăng nhiệt độ từ 20$^{0}$C đến 100$^{0}$C là 4560J","answer":true},{"text":"Nhiệt độ ban đầu của miếng đồng là 887, 5$^{0}$C","answer":true}]}$q$::jsonb, 198, $q$Nhiệt độ và cân bằng nhiệt$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Vận dụng ΔU = A + Q","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một động cơ của xe máy có hiệu suất là 20%. Sau một giờ hoạt động tiêu thụ hết 1 kg xăng có năng suất toả nhiệt là 46. 10$^{6}$ J/kg.</p>","explanation":"","statements":[{"text":"Khi 1 kg xăng cháy hết sẽ tỏa ra nhiệt lượng là 4,6. 10$^{6}$ J.","answer":false},{"text":"Tỉ số giữa công cơ học sinh ra và nhiệt lượng nguồn nóng là $\\frac{1}{2}$","answer":false},{"text":"Công cơ học do động cơ sinh ra có độ lớn là 92. 10$^{5}$ J.","answer":true},{"text":"Công suất của động cơ xe máy là 2555,56 W.","answer":true}]}$q$::jsonb, 200, $q$Vận dụng ΔU = A + Q$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Vận dụng ΔU = A + Q","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một động cơ ô tô hoạt động trong thời gian $\\frac{10}{3}$ h tiêu thụ hết 62 lít xăng. Biết hiệu suất động cơ là 30%, năng suất tỏa nhiệt của xăng là q = 46.10$^{6}$J/kg và khối lượng riêng của xăng là D = 0,7kg/l</p>","explanation":"","statements":[{"text":"Khối lượng xăng mà động cơ tiêu thụ là 43,4 kg","answer":true},{"text":"Nhiệt lượng động cơ nhận được từ 62 lít xăng là 2852.10$^{6}$J","answer":false},{"text":"Công mà động cơ đã thực hiện là 598,92.10$^{6}$J","answer":true},{"text":"Công suất của động cơ là 179,676.10$^{6}$W","answer":false}]}$q$::jsonb, 200, $q$Vận dụng ΔU = A + Q$q$),
