($q${"type":"true_false","form":"bai_tap","topic":"Quá trình đẳng áp và định luật Charles","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một khối khí có thể tích $V_{1}$ = 4 lít, áp suất p = 2. 10$^{5}$ Pa và nhiệt độ $t_{1}$ = 57$^{∘}$C nhận công 40 J và bị nén đẳng áp.</p>","explanation":"","statements":[{"text":"Khối khí thực hiện một công có giá trị 40 J","answer":false},{"text":"Thể tích của khí sau khi nén bằng 3,9 lít","answer":false},{"text":"Nhiệt độ của khối khí sau khi nén bằng 313,5 C","answer":false},{"text":"Đồ thị biểu diễn khối khí trong hệ tọa độ (p, V) có diện tích phần dưới bằng độ lớn công mà khối khí nhận được.","answer":true}]}$q$::jsonb, 207, $q$Quá trình đẳng áp và định luật Charles$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Quá trình đẳng áp và định luật Charles","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một khối khí có áp suất $p_{1}$ = 3.10$^{3}$ Pa, thể tích $V_{1}$ = 0,005 m$^{3}$, nhiệt độ $t_{1}$ = 27$^{∘}$C. Được nung nóng đẳng áp đến nhiệt độ $t_{2}$ = 177$^{∘}$C</p>","explanation":"","statements":[{"text":"Áp suất của khí tại trạng thái (2) bằng áp suất của khí tại trạng thái (1).","answer":true},{"text":"Thể tích của khí ở trạng thái (2) bằng 7,5. 10$^{−3}$ m$^{3}$.","answer":true},{"text":"Công mà khối khí thực hiện được có độ lớn bằng 7,5 J.","answer":true},{"text":"Nếu nhiệt lượng mà khí nhận được là 20 J thì độ biến thiên nội năng của khí là 27,5 J","answer":false}]}$q$::jsonb, 207, $q$Quá trình đẳng áp và định luật Charles$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Phương trình Clapeyron – Mendeleev","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một chiếc xe tải vượt qua sa mạc Sahara. Chuyến đi bắt đầu vào sáng sớm khi nhiệt độ là 3,0$^{o}$C. Thể tích khí chứa trong mỗi lốp xe là 1,50 m$^{3}$ và áp suất trong các lốp xe là 3,42. 10$^{5}$ Pa. Coi khí trong lốp xe có nhiệt độ như ngoài trời, không thoát ra ngoài và thể tích lốp không thay đổi. Đến giữa trưa, nhiệt độ tăng lên đến 42$^{∘}$C.</p>","explanation":"","statements":[{"text":"Các phân tử khí trong lốp xe chuyển động liên tục và va chạm với thành lốp xe gây ra áp suất lên thành lốp.","answer":true},{"text":"Trong mỗi lốp xe có 164 mol khí","answer":false},{"text":"Khi đến giữa trưa, áp suất trong lốp là 3,9.10$^{5}$ Pa","answer":true},{"text":"Từ sáng sớm cho đến giữa trưa, độ tăng động năng tịnh tiến trung bình của một phân tử không khí là 9,5.10$^{−21}$ J","answer":false}]}$q$::jsonb, 210, $q$Phương trình Clapeyron – Mendeleev$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Động năng trung bình phân tử và nhiệt độ","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một khối khí He chứa trong bình có thể tích 5l, áp suất 1,5.10$^{5}$ (*N* / *m*$^{2}$ ) , nhiệt độ 27°*C* . Nén đẳng áp khối khí để mật độ phân tử tăng gấp hai lần.</p>","explanation":"","statements":[{"text":"Động năng trung bình của phân tử trước khi nén là 6,2.10$^{−21}$ J","answer":true},{"text":"Mật độ phân tử trước khi nén là 3,6.10$$^{{25}$m$}${−3}$","answer":true},{"text":"Nhiệt độ khí sau khi nén là 123$^{o}$C","answer":false},{"text":"Nhiệt lượng khí truyền cho bên ngoài là 562,5 J","answer":false}]}$q$::jsonb, 212, $q$Động năng trung bình phân tử và nhiệt độ$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Từ trường của nam châm và của dòng điện","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Hai dây dẫn thẳng được mắc song song gần nhau vào một giá treo. Sau khi cho dòng điện đi qua, hai dây dẫn ở trạng thái như hình bên. Trong các câu sau đây, câu nào <strong>đúng</strong>, <strong>sai</strong> ?</p>","explanation":"","statements":[{"text":"Tương tác của hai dòng điện là tương tác từ","answer":true},{"text":"Hai dây dẫn hút nhau chứng tỏ hai dòng điện chạy trong hai dây dẫn này cùng chiều","answer":true},{"text":"Nếu chiều dòng điện chạy trong hai dây dẫn ngược chiều nhau thì chúng vẫn hút nhau như trạng thái cũ","answer":false},{"text":"Sau khi ngắt dòng điện, hai dây dẫn vẫn hút nhau.","answer":false}]}$q$::jsonb, 214, $q$Từ trường của nam châm và của dòng điện$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Cảm ứng từ và đơn vị tesla","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Trong các câu sau đây, câu nào <strong>đúng, sai</strong> ?</p>","explanation":"","statements":[{"text":"Cảm ứng từ là một đại lượng vô hướng","answer":false},{"text":"Tiếp tuyến tại bất kì điểm nào trên đường sức từ đều có phương, chiều trùng với phương và chiều của vecto cảm ứng từ tại điểm đó.","answer":true},{"text":"Từ trường ở vùng không gian giữa hai cực của nam châm chữ U được xem là từ trường đều.","answer":true},{"text":"Trong trừ trường đều, các đường sức từ song song nhau nhưng vecto cảm ứng từ tại các điểm khác nhau lại không bằng nhau về độ lớn.","answer":false}]}$q$::jsonb, 233, $q$Cảm ứng từ và đơn vị tesla$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Từ trường của nam châm và của dòng điện","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Chỉ ra câu <strong>đúng, sai</strong> trong các câu sau</p>","explanation":"","statements":[{"text":"Dòng điện có thể tác dụng lực lên nam châm","answer":true},{"text":"Nam châm thẳng không thể tác dụng lực lên nam châm hình chữ U","answer":false},{"text":"Hai dòng điện có thể tương tác với nhau","answer":true},{"text":"Hai dòng điện không thể tương tác với nhau.","answer":false}]}$q$::jsonb, 214, $q$Từ trường của nam châm và của dòng điện$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Từ trường của nam châm và của dòng điện","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Để làm tăng từ trường của nam châm điện ta cần</p>","explanation":"","statements":[{"text":"Tăng cường độ dòng điện của nó","answer":true},{"text":"Đảo ngược chiều dòng điện trong nó","answer":false},{"text":"Thay lõi sắt của nó bằng lõi nhôm","answer":false},{"text":"Giữ nguyên cường độ dòng điện, tăng số vòng dây của nó.","answer":true}]}$q$::jsonb, 214, $q$Từ trường của nam châm và của dòng điện$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Viết biểu thức u, i theo thời gian","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một máy phát điện xoay chiều được sử dụng để cấp điện cho hộ gia đình sử dụng. Biết rằng dòng điện xoay chiều cung cấp có biểu thức $i=5\\sqrt{2}cos\\left( 100\\pi t \\right)$ trong đó $i$ tính bằng ampe, $ t$tính bằng giây.</p>","explanation":"","statements":[{"text":"Tần số của dòng điện là $f=0,02 Hz.$","answer":false},{"text":"Thời điểm ban đầu dòng điện có độ lớn $5 A.$","answer":false},{"text":"Thời gian ngắn nhất để cường độ dòng điện giảm từ $5\\sqrt{2} \\left( A \\right)$ về $0\\left( A \\right)$ là $ t=0,005 s.$","answer":true},{"text":"Trong một chu kì, khoảng thời gian để cường độ dòng điện có độ lớn không vượt quá $5\\left( A \\right)$ là $0,01\\left( s \\right)$","answer":true}]}$q$::jsonb, 220, $q$Viết biểu thức u, i theo thời gian$q$)) as v(q, tid, tname)
