from (values ($q${"type":"true_false","form":"bai_tap","topic":"Giá trị hiệu dụng của dòng điện xoay chiều","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một đoạn mạch điện xoay chiều chỉ có điện trở thuần với giá trị 200 Ω. Đặt hiệu điện thế $u=100\\sqrt{2}cos\\left( 100\\pi t \\right)V$ vào hai đầu đoạn mạch trên thì:</p>","explanation":"","statements":[{"text":"hiệu điện thế đặt vào hai đầu đoạn mạch có giá trị hiệu dụng bằng 100 V.","answer":true},{"text":"dòng điện chạy trong mạch có tần số 50 Hz.","answer":true},{"text":"công suất toả nhiệt trên điện trở bằng 50 W.","answer":true},{"text":"dòng điện chạy trong mạch có giá trị hiệu dụng bằng $\\frac{\\sqrt{2}}{2} A$.","answer":false}]}$q$::jsonb, 219, $q$Giá trị hiệu dụng của dòng điện xoay chiều$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một hạt nhân nguyên tử có ký hiệu $_{25}^{55}Mn$. Trong các nhận định dưới đây, nhận định nào là đúng, nhận định nào là sai?\\</p>","explanation":"","statements":[{"text":"Nguyên tố Mn đứng ở ô số 55 trong bảng hệ thống tuần hoàn.","answer":false},{"text":"Hạt nhân $_{25}^{55}Mn$ có điện tích +25 e .","answer":true},{"text":"Hạt nhân $_{25}^{55}Mn$ chứa 30 nucleon trung hoà.","answer":true},{"text":"Nguyên tử $_{25}^{55}Mn$ có 25 electron quay quanh hạt nhân.","answer":true}]}$q$::jsonb, 221, $q$Kí hiệu hạt nhân, số nuclôn, đồng vị$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Silic $(Si)$ hay còn được gọi là silicon (nguyên tố phổ biến thứ hai trong vỏ Trái Đất sau oxygen) là vật liệu bán dẫn được sử dụng phổ biến trong ngành công nghiệp điện tử.\\</p>","explanation":"","statements":[{"text":"Số electron nguyên tử silicon $_{14}^{28}Si$ là 14","answer":true},{"text":"Số proton nguyên tử silicon $_{14}^{28}Si$ là 14","answer":true},{"text":"Số neutron trong nguyên tử silicon $_{14}^{28}Si$ là 28","answer":false},{"text":"Điện tích của hạt nhân $_{14}^{28}Si$ là +14 e","answer":true}]}$q$::jsonb, 221, $q$Kí hiệu hạt nhân, số nuclôn, đồng vị$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Titanium là vật liệu \\\"nhẹ̣\\\", bền, cứng, chịu nhiệt tốt và khó bị oxy hoá. Do đó titanium được sử dụng nhiều trong ngành công nghiệp hàng không - vũ trụ.\\</p>","explanation":"","statements":[{"text":"Số electron trong nguyên tử titanium $_{22}^{48}Ti$ là 22","answer":true},{"text":"Số proton trong nguyên tử titanium $_{22}^{48}Ti$ là 22","answer":true},{"text":"Số neutron trong nguyên tử titanium $_{22}^{48}Ti$ là 26","answer":true},{"text":"Điện tích của hạt nhân $_{22}^{48}Ti$ là +22 e","answer":true}]}$q$::jsonb, 221, $q$Kí hiệu hạt nhân, số nuclôn, đồng vị$q$)) as v(q, tid, tname)
